#!/usr/bin/env python3
"""Generate a full Website_name project from embedded data.

This script is self-contained: it does not copy from an existing source folder.
It rebuilds files/folders from data embedded below.
"""

from __future__ import annotations

import argparse
import base64
import io
import shutil
import sys
import zipfile
from pathlib import Path

PROJECT_FOLDER_NAME = "Website_name"
EXPECTED_DIRS = 26
EXPECTED_FILES = 35

EMPTY_DIRS = [
    '.vscode',
    'backend',
    'backend/config',
    'backend/controllers',
    'backend/middleware',
    'backend/models',
    'backend/public',
    'backend/routes',
    'backend/services',
    'frontend',
    'frontend/public',
    'frontend/src',
    'frontend/src/api',
    'frontend/src/assets',
    'frontend/src/components',
    'frontend/src/components/Footer',
    'frontend/src/components/Header',
    'frontend/src/components/Loader',
    'frontend/src/components/ScrollToTop',
    'frontend/src/pages',
    'frontend/src/pages/About',
    'frontend/src/pages/Admin',
    'frontend/src/pages/Contact',
    'frontend/src/pages/Home',
    'frontend/src/pages/NotFound',
    'frontend/src/pages/Profile',
]

EMBEDDED_ZIP_BASE64 = """"""


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Generate the exact Website_name structure and files from embedded data."
    )
    parser.add_argument(
        "--output",
        default=PROJECT_FOLDER_NAME,
        help="Output folder path (default: Website_name)",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Delete output folder first if it already exists.",
    )
    return parser.parse_args()


def build_project(output_path: Path, force: bool) -> tuple[int, int]:
    if output_path.exists():
        if not force:
            raise FileExistsError(
                f"Output folder already exists: {output_path}. Use --force to replace it."
            )
        shutil.rmtree(output_path)

    output_path.mkdir(parents=True, exist_ok=True)

    for rel_dir in EMPTY_DIRS:
        (output_path / rel_dir).mkdir(parents=True, exist_ok=True)

    zip_bytes = base64.b64decode(EMBEDDED_ZIP_BASE64.encode("ascii"))
    with zipfile.ZipFile(io.BytesIO(zip_bytes), "r") as archive:
        members = archive.infolist()

        # Protect against path traversal if the embedded data is tampered with.
        for info in members:
            member_path = (output_path / info.filename).resolve()
            if output_path not in member_path.parents and member_path != output_path:
                raise ValueError(f"Unsafe archive member path: {info.filename}")

        archive.extractall(output_path)
        file_count = len([info for info in members if not info.is_dir()])

    dir_count = len(EMPTY_DIRS)

    if dir_count != EXPECTED_DIRS or file_count != EXPECTED_FILES:
        raise ValueError(
            "Integrity check failed after generation: "
            f"expected dirs/files {EXPECTED_DIRS}/{EXPECTED_FILES}, "
            f"got {dir_count}/{file_count}."
        )

    return dir_count, file_count


def main() -> int:
    args = parse_args()
    output_path = Path(args.output).expanduser().resolve()

    try:
        dir_count, file_count = build_project(output_path=output_path, force=args.force)
    except FileExistsError as err:
        print(f"Error: {err}")
        return 1
    except (ValueError, zipfile.BadZipFile, OSError) as err:
        print(f"Error: {err}")
        return 1

    print("Project generated successfully from embedded snapshot.")
    print(f"Output : {output_path}")
    print(f"Folders: {dir_count}")
    print(f"Files  : {file_count}")
    return 0


if __name__ == "__main__":
    sys.exit(main())